package dev.gromclient.visuals;
import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.Click;import net.minecraft.client.gui.screen.Screen;import net.minecraft.text.Text;
/** Pixel-grid studio for a client-side custom crosshair. */
public final class CrosshairEditorScreen extends Screen {
 private int cx,cy,cell=10;private static final int PURPLE=0xFFB66BFF,WHITE=0xFFF6F2FF,MUTED=0xFFB5A9C4;
 public CrosshairEditorScreen(){super(Text.literal("Grom Visuals — Crosshair Studio"));}
 @Override protected void init(){cell=Math.max(7,Math.min(13,Math.min((width-100)/21,(height-130)/21)));cx=(width-21*cell)/2;cy=(height-21*cell)/2+10;}
 @Override public void render(DrawContext d,int mx,int my,float delta){d.fill(0,0,width,height,0xF5080710);for(int y=0;y<height;y+=5)d.fill(0,y,width,y+1,0x183D1761);d.fill(18,18,width-18,height-18,0xFFB66BFF);d.fill(19,19,width-19,height-19,0xF20D0B13);d.fill(19,19,width-19,82,0xFF171020);d.drawText(textRenderer,"GROM VISUALS",34,30,PURPLE,false);d.drawText(textRenderer,"CROSSHAIR STUDIO",34,48,WHITE,false);d.drawText(textRenderer,"Click cells to draw • click again to erase",cx,cy-20,MUTED,false);
  VisualConfig c=GromVisualsClient.CONFIG;for(int y=0;y<21;y++)for(int x=0;x<21;x++){int ax=cx+x*cell,ay=cy+y*cell;d.fill(ax,ay,ax+cell-1,ay+cell-1,c.crosshairPixels[y*21+x]!=0?c.crosshairColor:((x==10||y==10)?0xFF282230:0xFF17141D));if(x==10&&y==10)d.fill(ax,ay,ax+cell-1,ay+cell-1,0xFF5A456A);}
  int by=height-58;button(d,30,by,88,"PURPLE",c.crosshairColor==0xFFB66BFF,0xFFB66BFF);button(d,124,by,80,"CYAN",c.crosshairColor==0xFF35E6FF,0xFF35E6FF);button(d,210,by,80,"WHITE",c.crosshairColor==0xFFFFFFFF,0xFFFFFFFF);button(d,296,by,88,"ORANGE",c.crosshairColor==0xFFFF7A35,0xFFFF7A35);button(d,width-390,by,130,"MINECRAFT CROSSHAIR",false,0xFF4C8DA8);button(d,width-250,by,92,"CLEAR",false,0xFF332638);button(d,width-151,by,121,"SAVE & ENABLE",true,PURPLE);d.drawText(textRenderer,"PIXEL SIZE: "+c.crosshairCellSize+" (click here to change)",cx,cy+21*cell+8,WHITE,false);}
 private void button(DrawContext d,int x,int y,int w,String t,boolean selected,int accent){d.fill(x,y,x+w,y+25,selected?0xFF342440:0xFF211A29);d.fill(x,y,x+w,y+2,accent);d.drawText(textRenderer,t,x+(w-textRenderer.getWidth(t))/2,y+9,WHITE,false);}
 @Override public boolean mouseClicked(Click click,boolean dbl){if(click.button()!=0)return super.mouseClicked(click,dbl);int x=(int)click.x(),y=(int)click.y(),by=height-58;VisualConfig c=GromVisualsClient.CONFIG;
  if(x>=cx&&x<cx+21*cell&&y>=cy&&y<cy+21*cell){int i=((y-cy)/cell)*21+(x-cx)/cell;c.crosshairPixels[i]=c.crosshairPixels[i]==0?1:0;return true;}
  if(y>=by&&y<=by+25){if(x>=30&&x<=118)c.crosshairColor=0xFFB66BFF;else if(x>=124&&x<=204)c.crosshairColor=0xFF35E6FF;else if(x>=210&&x<=290)c.crosshairColor=0xFFFFFFFF;else if(x>=296&&x<=384)c.crosshairColor=0xFFFF7A35;else if(x>=width-390&&x<=width-260){c.crosshair=false;c.customCrosshair=false;c.save();client.setScreen(new VisualsScreen());}else if(x>=width-250&&x<=width-158)c.crosshairPixels=new int[441];else if(x>=width-151&&x<=width-30){c.crosshair=true;c.customCrosshair=true;c.save();client.setScreen(new VisualsScreen());}return true;}
  if(y>=cy+21*cell+4&&y<=cy+21*cell+26){c.crosshairCellSize=c.crosshairCellSize>=10?2:c.crosshairCellSize+1;return true;}return super.mouseClicked(click,dbl);}
 @Override public boolean shouldPause(){return false;}
}
